recipes.code:
{
  "inputs": [
    {
      "id": "homespun-api-key",
      "type": "promptString",
      "description": "Homespun agent API key. If unset, the server auto-registers a fresh agent against the relay on first use and saves the key to the shared CLI store (~/.config/homespun/config.json).",
      "password": true
    },
    {
      "id": "homespun-register-secret",
      "type": "promptString",
      "description": "Registration secret, required only for relays running REGISTRATION_MODE=secret.",
      "password": true
    }
  ],
  "servers": {
    "homespun": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@homespunapps/mcp@1.6.41"
      ],
      "env": {
        "HOMESPUN_API_KEY": "${input:homespun-api-key}",
        "HOMESPUN_URL": "<homespun-url>",
        "HOMESPUN_AGENT_NAME": "<homespun-agent-name>",
        "HOMESPUN_REGISTER_SECRET": "${input:homespun-register-secret}"
      }
    }
  }
}
